export type StreamControl = { bytes: number; type: "credit" } | { first_missing_offset: string; missing_bytes: string; type: "terminal_gap" } | { total_bytes: string; type: "terminal_finished" } | { sha256: Sha256Digest; total_bytes: string; type: "artifact_finished" };

export type TerminalState = "opening" | "open" | "closing" | "closed" | "unavailable";

export type TerminationStage = "native_cancellation" | "interrupt" | "terminate" | "kill" | "unobserved";

export type ToolAvailability = { status: "present"; version: string } | { status: "missing" };

export type Turn = { client_id: string; run_id?: string | null; sequence: string; source: TurnSource; state: TurnState; turn_id: string };

export type TurnOutcome = "completed" | "interrupted";

export type TurnQueue = { cursor: string; turns: Array<Turn> };

export type TurnSource = "user" | "schedule" | "auto_continue";

export type TurnState = "queued" | "active" | "completed" | "superseded" | "canceled" | "withdrawn" | "failed" | "outcome_unknown";

export type UtilityJob = { binding_id?: string | null; job_id: string; model?: string | null; outcome: UtilityOutcome; plane_id: string; policy: UtilityPolicy; provider?: string | null; purpose: UtilityPurpose };

export type UtilityOutcome = { status: "pending" } | { inactive_days: number; status: "draft" } | { body: string; fallback_reason?: string | null; status: "text"; text: string } | { reason: string; status: "refused" };

export type UtilityPolicy = { cross_provider_consent: boolean; enabled: boolean; version: number };

export type UtilityPurpose = "naming" | "git_text" | "autodelete";

export type UtilityRequest = { purpose: "naming"; run_id: string } | { purpose: "git_text"; run_id: string; turn: number } | { prompt: string; purpose: "autodelete" };

export type VersionRange = { max: number; min: number };

export type WireError = { category: ErrorCategory; code: string; message: string; recovery_actions?: Array<RecoveryAction>; restart?: RestartMetadata | null; retryable: boolean; revision_conflict?: RevisionConflict | null };

export type WorkingTree = { kind: "no_project" } | { kind: "workspace"; project_id: string } | { kind: "local_checkout"; project_id: string };

export type WorkingTreeRequest = { kind: "no_project" } | { base?: BaseSelection; kind: "workspace"; project_id: string; seed?: SeedSelection } | { kind: "local_checkout"; project_id: string };

export type Workspace = { base: WorkspaceBase; conversation_id: string; created_at_unix_ms: number; project_id: string; promotion?: WorkspacePromotion | null; root: string; seed?: WorkspaceSeed | null; workspace_id: string };

export type WorkspaceBase = { commit: string; selection: BaseSelection };

export type WorkspacePromotion = { binding: PromotionBinding; changed_paths: number; promotion_id: string; recorded_at_unix_ms: number; settled_at_unix_ms?: number | null; state: PromotionState };

export type WorkspaceSeed = { changed_paths: number; tree: string };

export type WorkspaceTerminal = { state: TerminalState; terminal_id: string; workspace_id: string };

export type Worktree = { kind: "main" } | { common_dir: string; kind: "linked" };
